import axiosClient from '../api/axiosClient';

const productService = {
    /**
     * Lấy toàn bộ danh sách sản phẩm (Đã có link ảnh tuyệt đối từ API)
     * URL: GET /api/products
     */
    getAllProducts: () => {
        const url = '/products';
        return axiosClient.get(url);
    },

    /**
     * Lấy chi tiết một sản phẩm theo ID
     * URL: GET /api/products/{id}
     */
    getProductById: (id) => {
        const url = `/products/${id}`;
        return axiosClient.get(url);
    },

    /**
     * Lấy sản phẩm dựa theo danh mục
     * URL: GET /api/products/category/{categoryId}
     */
    getProductsByCategory: (categoryId) => {
        const url = `/products/category/${categoryId}`;
        return axiosClient.get(url);
    },

    /**
     * Thêm mới sản phẩm (Hỗ trợ truyền file hình ảnh trực tiếp)
     * URL: POST /api/products
     * @param {FormData} formData - Chứa các trường Name, Price, Description, StockQuantity, CategoryProductId và UploadImage (File)
     */
    createProduct: (formData) => {
        const url = '/products';
        return axiosClient.post(url, formData, {
            headers: {
                'Content-Type': 'multipart/form-data'
            }
        });
    },

    /**
     * Cập nhật thông tin sản phẩm (Hỗ trợ đè file hình ảnh mới nếu có)
     * URL: PUT /api/products/{id}
     * @param {number} id - ID sản phẩm cần sửa
     * @param {FormData} formData - Chứa thông tin cập nhật
     */
    updateProduct: (id, formData) => {
        const url = `/products/${id}`;
        return axiosClient.put(url, formData, {
            headers: {
                'Content-Type': 'multipart/form-data'
            }
        });
    },

    /**
     * Xóa sản phẩm
     * URL: DELETE /api/products/{id}
     */
    deleteProduct: (id) => {
        const url = `/products/${id}`;
        return axiosClient.delete(url);
    }
};

export default productService;
